$ErrorActionPreference='Stop'
$taskRoot=(Resolve-Path (Join-Path $PSScriptRoot '../../..')).Path
function Records($taskPaths,[string]$taskAction){@(foreach($taskPath in $taskPaths){[ordered]@{path=$taskPath;sha256=(Get-FileHash -LiteralPath (Join-Path $taskRoot $taskPath) -Algorithm SHA256).Hash;action=$taskAction;owner='R3 010';consumer='UI/Support/SupportPanels.tscn';dependencies=@('R3 009 shared UI direction','existing content and R3 007 cast')}})}
$taskFiles=Records @('assets/ui/support/r3_v1/panels.json','assets/ui/support/r3_v1/portrait-index.json','assets/ui/support/r3_v1/retained-content.json') 'new'
$taskSources=Records @('Scripts/UI/Support/support_panels.gd','Scripts/UI/Support/support_style.gd','Scripts/UI/Support/science_card.gd','UI/Support/SupportPanels.tscn','tools/art/support_r3_v1/build_content.gd','tools/art/support_r3_v1/build.ps1','tools/art/support_r3_v1/catalog.ps1','tools/art/support_r3_v1/generation.md') 'new'
$taskReuse=@('Scripts/Content/level_questions.gd','Scripts/Content/level_registry.gd','Scripts/Content/phase_transition_rules.gd','Scripts/UI/mechanic_visual.gd','Scripts/Autoload/achievement_registry.gd','Scripts/UI/achievement_icon.gd','Scripts/UI/quest_frame.gd','Scripts/UI/quest_ui.gd','Scripts/UI/achievement_toast.gd','UI/HUD/AchievementToast.tscn','assets/ui/ranks/rank_badges.png','assets/fonts/InterfaceSans.tres','assets/fonts/PhasequestUI.ttf','assets/fonts/OFL.txt')
$taskCast=Get-Content -LiteralPath (Join-Path $taskRoot 'assets/characters/professors/r3_v1/cast_registry.json') -Raw|ConvertFrom-Json
foreach($taskRole in $taskCast.actors.PSObject.Properties){foreach($taskPortrait in $taskRole.Value.portraits.PSObject.Properties){$taskReuse+=$taskPortrait.Value.Substring(6)}}
$taskRetained=Records $taskReuse 'keep'
$taskFamilies=@('ui.dialogue.professor','ui.guides.help.demos','ui.science.diagrams','ui.journal.achievements_rank','ui.crafting_finn','ui.assessment','ui.settings_recovery_errors','ui.theme_fonts_icons')
$taskPanels=Get-Content -LiteralPath (Join-Path $taskRoot 'assets/ui/support/r3_v1/panels.json') -Raw|ConvertFrom-Json
$taskPanelCount=@($taskPanels.panels.PSObject.Properties).Count
[ordered]@{schema_version=1;owner='R3 010';status='Implemented—needs verification; user/teacher/physical Android pending';families=$taskFamilies;scene='UI/Support/SupportPanels.tscn';panel_states=$taskPanelCount;files=$taskFiles;presentation_sources=$taskSources;reused=$taskRetained;retained_question_banks=3;retained_questions=11;retained_badge_ids=32;routes=@('melting','freezing','evaporation','boiling','condensation','sublimation','deposition');minimum_body_font_ui=16;minimum_action_ui=44;full_text='Vertical scrolling with fixed actions; feedback brought into view; no full body ellipsis';accessibility='Larger text, contrast, focus-follow scroll, neutral touch labels, static reduced motion and text alternatives';production_binding='015/023/046/047; no real services, assessment scoring or save/award/consumption in these assets';retirement_eligible=$false}|ConvertTo-Json -Depth 12|Set-Content -LiteralPath (Join-Path $taskRoot 'assets/ui/support/r3_v1/catalog.json') -Encoding utf8
$taskManifestPath=Join-Path $taskRoot 'docs/audits/r3-prompt001/asset-manifest.json'
$taskManifest=Get-Content -LiteralPath $taskManifestPath -Raw|ConvertFrom-Json -AsHashtable
foreach($taskFamily in $taskManifest.families){if($taskFamily.id -notin $taskFamilies){continue};$taskFamily.review_status='R3 010 shared opt-in support layouts implemented—needs verification; content/user/teacher/Android/provider integration pending';$taskFamily.r3_010=[ordered]@{owner='R3 010';catalog='assets/ui/support/r3_v1/catalog.json';coverage='docs/art/r3-prompt010/coverage.json';evidence='docs/art/r3-prompt010/evidence/results.json';consumer='UI/Support/SupportPanels.tscn';dependencies=@('R3 009 shared UI direction','R3 007 cast and original content','015/023/046/047 authoritative providers');disposition='New shared presentation with retained original content/assets; old consumers kept';replacement_dependency='Integrate and regress before eligible retirement; no deletion here';retirement_eligible=$false}}
$taskManifest|ConvertTo-Json -Depth 40|Set-Content -LiteralPath $taskManifestPath -Encoding utf8
Write-Output ('R3 010 catalog / '+$taskPanelCount+' states /8family bindings / '+$taskRetained.Count+' retained sources')
